def hidden_rule_fn(state):
    def is_prime(n):
        if n < 2:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        for i in range(3, int(n**0.5) + 1, 2):
            if n % i == 0:
                return False
        return True

    n = len(state)
    new_val = 0
    if is_prime(n):
        new_val = (state[n - 1] ^ state[n - 2]) % 7
    else:
        # n is not prime, n >= 4 based on training data
        new_val = (state[n - 1] + state[n - 2] + 3) % 7

    return state + [new_val]
